// === DADOS — 20 times com escudos REAIS (do código original Fase1.as) ===
const TEAMS = [
  { id: "america-rn",     n: "América" },
  { id: "atletico-mg",    n: "Atlético Mineiro" },
  { id: "atletico-pr",    n: "Atlético Paranaense" },
  { id: "avai",           n: "Avaí" },
  { id: "botafogo",       n: "Botafogo" },
  { id: "corinthians",    n: "Corinthians" },
  { id: "coritiba",       n: "Coritiba" },
  { id: "cruzeiro",       n: "Cruzeiro" },
  { id: "flamengo",       n: "Flamengo" },
  { id: "fluminense",     n: "Fluminense" },
  { id: "goias",          n: "Goiás" },
  { id: "gremio",         n: "Grêmio" },
  { id: "internacional",  n: "Inter" },
  { id: "nautico",        n: "Náutico" },
  { id: "palmeiras",      n: "Palmeiras" },
  { id: "santos",         n: "Santos" },
  { id: "sao-paulo",      n: "São Paulo" },
  { id: "sport",          n: "Sport" },
  { id: "vasco",          n: "Vasco" },
  { id: "vitoria",        n: "Vitória" },
];

function sortear2() {
  const i = Math.floor(Math.random() * TEAMS.length);
  let j; do { j = Math.floor(Math.random() * TEAMS.length); } while (j === i);
  return [TEAMS[i], TEAMS[j]];
}

// === LÓGICA — fiel ao Fase1.as do OVA original ===
const trunc2 = (x) => Math.floor(x * 100) / 100;
const vir = (x) => String(trunc2(x)).replace(".", ",");
const aleat = () => Math.round(Math.random() * 50);

function distrator(r) {
  const b = parseFloat(r);
  let v, t = 0;
  // Replica sortearAlternativas: Number(param1) * Math.random() * 3
  do { v = trunc2(b * Math.random() * 3); t++; } while ((v === b || v < 0 || v > 1) && t < 20);
  if (v === b || v < 0 || v > 1) v = trunc2(Math.random());
  return v;
}

function novaQ() {
  const [t1, t2] = sortear2();
  const H1 = aleat(), H2 = aleat(), M1 = aleat(), M2 = aleat();
  const T = H1 + H2 + M1 + M2;
  if (T < 10) return novaQ();
  // Espelha tipoQuestao = Math.round(Math.random() * (4-1)) → 0..3
  const tipo = Math.floor(Math.random() * 4);
  let enun, rN, fmla, passos;
  switch (tipo) {
    case 0:
      enun = "Qual é a probabilidade de se entrevistar, ao acaso, uma pessoa do sexo feminino?";
      rN = (M1 + M2) / T;
      fmla = "P(F) = n(F) / n(S)";
      passos = [
        `Identificamos o evento F = "ser do sexo feminino".`,
        `Casos favoráveis: n(F) = ${M1} + ${M2} = ${M1+M2}.`,
        `Espaço amostral: n(S) = ${T}.`,
        `P(F) = ${M1+M2} / ${T} ≈ ${vir(rN)}.`,
      ];
      break;
    case 1:
      enun = `Se uma pessoa é entrevistada ao acaso, qual é a probabilidade dela ser da torcida do ${t1.n} OU do sexo masculino?`;
      rN = (H1 + H2 + M1) / T;
      fmla = "P(A ∪ B) = P(A) + P(B) − P(A ∩ B)";
      passos = [
        `Evento A = "torcer pelo ${t1.n}"; Evento B = "ser homem".`,
        `P(A) = ${H1+M1}/${T}; P(B) = ${H1+H2}/${T}.`,
        `P(A ∩ B) = ${H1}/${T} (homens do ${t1.n}).`,
        `P(A ∪ B) = (${H1+M1} + ${H1+H2} − ${H1})/${T} = ${H1+H2+M1}/${T} ≈ ${vir(rN)}.`,
      ];
      break;
    case 2:
      enun = `Se uma pessoa é entrevistada ao acaso, qual é a probabilidade dela ser do sexo masculino E ser torcedor do ${t2.n}?`;
      rN = H2 / T;
      fmla = "P(A ∩ B) = n(A ∩ B) / n(S)";
      passos = [
        `Pessoas que são homens E torcem pelo ${t2.n}.`,
        `n(A ∩ B) = ${H2}.`,
        `n(S) = ${T}.`,
        `P(A ∩ B) = ${H2} / ${T} ≈ ${vir(rN)}.`,
      ];
      break;
    default:
      enun = `Se duas pessoas são entrevistadas na sequência, qual é a probabilidade da primeira ser um homem e torcer para o ${t1.n} e da segunda ser mulher e torcer para o ${t2.n}? Obs: a mesma pessoa pode ser entrevistada duas vezes.`;
      rN = (H1 / T) * (M2 / T);
      fmla = "P(A ∩ B) = P(A) · P(B)";
      passos = [
        `Eventos sucessivos COM reposição ⇒ independentes.`,
        `P(A) = ${H1}/${T} (homem do ${t1.n}).`,
        `P(B) = ${M2}/${T} (mulher do ${t2.n}).`,
        `P(A ∩ B) = (${H1}/${T}) × (${M2}/${T}) ≈ ${vir(rN)}.`,
      ];
  }
  const rC = trunc2(rN);
  const pos = Math.floor(Math.random() * 5);
  const alts = []; const usadas = new Set([rC]);
  for (let i = 0; i < 5; i++) {
    if (i === pos) alts.push(rC);
    else {
      let d, t = 0;
      do { d = distrator(rC); t++; } while (usadas.has(d) && t < 20);
      usadas.add(d); alts.push(d);
    }
  }
  // Totais corretos a serem digitados pelo aluno
  const totalsCorretos = {
    t1: H1 + M1,        // total de torcedores do time 1 (linha)
    t2: H2 + M2,        // total de torcedores do time 2 (linha)
    th: H1 + H2,        // total de homens (coluna)
    tm: M1 + M2,        // total de mulheres (coluna)
    tg: T,              // total geral
  };
  return { tipo, t1, t2, H1, H2, M1, M2, T, enun, fmla, passos, rC, alts, pos, totalsCorretos };
}

