// === Tabela com TOTAIS EDITÁVEIS pelo aluno ===
function Tabela({ q, totals, setTotals, locked, somaResult }) {
  function update(key, raw) {
    const val = raw.replace(/[^\d]/g, "").slice(0, 4);
    setTotals({ ...totals, [key]: val });
  }
  // Cada total tem 3 estados: untouched ("") / right / wrong
  function classFor(key) {
    if (locked) return "tot-input right";
    if (somaResult && somaResult[key] === false) return "tot-input wrong";
    if (somaResult && somaResult[key] === true)  return "tot-input right";
    return "tot-input";
  }
  return (
    <div className="panel-silver">
      <div className="panel-inner">
        <table className="tab-cont">
          <caption className="sr-only">Espaço amostral: torcedores entrevistados.</caption>
          <thead>
            <tr>
              <th className="corner"></th>
              <th><span className="gm">♂</span></th>
              <th><span className="gf">♀</span></th>
              <th>Total</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <th><Escudo team={q.t1} /><div className="tn">{q.t1.n}</div></th>
              <td className="num">{q.H1}</td>
              <td className="num">{q.M1}</td>
              <td>
                <input className={classFor("t1")} value={totals.t1} disabled={locked}
                  onChange={(e) => update("t1", e.target.value)}
                  aria-label={`Total de torcedores do ${q.t1.n}`}
                  inputMode="numeric" placeholder="?" />
              </td>
            </tr>
            <tr>
              <th><Escudo team={q.t2} /><div className="tn">{q.t2.n}</div></th>
              <td className="num">{q.H2}</td>
              <td className="num">{q.M2}</td>
              <td>
                <input className={classFor("t2")} value={totals.t2} disabled={locked}
                  onChange={(e) => update("t2", e.target.value)}
                  aria-label={`Total de torcedores do ${q.t2.n}`}
                  inputMode="numeric" placeholder="?" />
              </td>
            </tr>
            <tr>
              <th className="ttot">TOTAL</th>
              <td>
                <input className={classFor("th")} value={totals.th} disabled={locked}
                  onChange={(e) => update("th", e.target.value)} aria-label="Total de homens"
                  inputMode="numeric" placeholder="?" />
              </td>
              <td>
                <input className={classFor("tm")} value={totals.tm} disabled={locked}
                  onChange={(e) => update("tm", e.target.value)} aria-label="Total de mulheres"
                  inputMode="numeric" placeholder="?" />
              </td>
              <td>
                <input className={classFor("tg")} value={totals.tg} disabled={locked}
                  onChange={(e) => update("tg", e.target.value)} aria-label="Total geral"
                  inputMode="numeric" placeholder="?" />
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

