function Spiral({ q, sel, onSel }) {
  const [c, setC] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    setC(0);
    function step() {
      setC((p) => Math.min(p + 2, 360));
      ref.current = requestAnimationFrame(step);
    }
    ref.current = requestAnimationFrame(step);
    return () => { if (ref.current) cancelAnimationFrame(ref.current); };
  }, [q]);
  useEffect(() => {
    if (c >= 360 && ref.current) { cancelAnimationFrame(ref.current); ref.current = null; }
  }, [c]);
  const cx = 200, cy = 200;
  const r = c * (50 / 180) * 1.6;
  return (
    <div role="radiogroup" aria-label="Alternativas" style={{ position: "relative", width: cx * 2, height: cy * 2, margin: "0 auto", maxWidth: "100%" }}>
      {q.alts.map((a, i) => {
        const ang = ((c + i * 72 - 18) / 180) * Math.PI;
        const x = cx + Math.cos(ang) * r;
        const y = cy + Math.sin(ang) * r;
        const s = sel === i;
        return (
          <button key={i} role="radio" aria-checked={s} aria-label={`Alternativa ${i+1}: ${vir(a)}`}
            className={"alt" + (s ? " sel" : "")} style={{ left: x, top: y, border: 0 }}
            onClick={() => onSel(i)}>{vir(a)}</button>
        );
      })}
    </div>
  );
}

