const TOPICS = [
  { id: "geral", l: "GERAL" }, { id: "umEvento", l: "EVENTO" },
  { id: "uniao", l: "UNIÃO" }, { id: "sucessivos", l: "SUCESSIVOS" },
  { id: "condicional", l: "CONDICIONAL" },
];

function Help({ open, topic, setTopic, onClose }) {
  const [pg, setPg] = useState(0);
  useEffect(() => { setPg(0); }, [topic]);
  useEffect(() => {
    if (!open) return;
    function k(e) {
      if (e.key === "Escape") onClose();
      const max = (HELP[topic]?.p.length || 1) - 1;
      if (e.key === "ArrowRight") setPg((p) => Math.min(p + 1, max));
      if (e.key === "ArrowLeft") setPg((p) => Math.max(p - 1, 0));
    }
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, topic, onClose]);
  if (!open) return null;
  const c = HELP[topic] || HELP.geral;
  const p = c.p[pg] || {};
  return (
    <div className="modal-bg" onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div role="dialog" aria-modal="true" className="modal metal-frame">
        <div className="metal-inner modal-i">
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
            <h2 className="title-flash" style={{ fontSize: 22, margin: 0 }}>📚 AJUDA</h2>
            <button type="button" className="btn small ghost" onClick={onClose}>✕ Fechar</button>
          </div>
          <div className="tabs" role="tablist">
            {TOPICS.map((t) => (
              <button key={t.id} role="tab" aria-selected={topic === t.id}
                className={"tab" + (topic === t.id ? " act" : "")}
                onClick={() => setTopic(t.id)}>{t.l}</button>
            ))}
          </div>
          <div className="help-body" role="tabpanel">
            <h3>{c.t}</h3>
            {p.h && <h4 style={{ margin: "0 0 6px 0", color: "#d61f7a" }}>{p.h}</h4>}
            {p.x && <p style={{ whiteSpace: "pre-line" }}>{p.x}</p>}
            {p.f && <span className="formula">{p.f}</span>}
            {p.e && <div className="examples">{p.e}</div>}
          </div>
          <div className="pag">
            <button type="button" className="btn small ghost" onClick={() => setPg((p) => Math.max(p - 1, 0))}
              disabled={pg === 0} style={{ visibility: pg === 0 ? "hidden" : "visible" }}>← Voltar</button>
            <div className="dots">
              {c.p.map((_, i) => (
                <button key={i} type="button" className={"dot" + (i === pg ? " act" : "")}
                  onClick={() => setPg(i)} aria-label={`Página ${i+1}`} />
              ))}
            </div>
            <button type="button" className="btn small" onClick={() => setPg((p) => Math.min(p + 1, c.p.length - 1))}
              disabled={pg === c.p.length - 1} style={{ visibility: pg === c.p.length - 1 ? "hidden" : "visible" }}>Avançar →</button>
          </div>
        </div>
      </div>
    </div>
  );
}


// === Calculadora — adição, subtração, divisão (operações pedidas) ===
function Calculator({ open, onClose }) {
  const [display, setDisplay] = useState("0");
  const [prev, setPrev]       = useState(null);
  const [op, setOp]           = useState(null);
  const [justEval, setJustEval] = useState(false);

  // === DRAG STATE (posição arrastável da calculadora) ===
  const CALC_W = 246, CALC_H = 340;
  const [pos, setPos] = useState(() => {
    // Posição inicial: canto inferior esquerdo, 80px acima do botão fixo
    if (typeof window === "undefined") return { x: 16, y: 100 };
    return { x: 16, y: Math.max(60, window.innerHeight - CALC_H - 70) };
  });
  const [dragging, setDragging] = useState(false);
  const dragRef = useRef({ mx: 0, my: 0, sx: 0, sy: 0 });

  // Reposiciona se a janela for redimensionada (mantém sempre visível)
  useEffect(() => {
    function onResize() {
      setPos((p) => ({
        x: Math.max(0, Math.min(window.innerWidth - CALC_W, p.x)),
        y: Math.max(0, Math.min(window.innerHeight - CALC_H, p.y)),
      }));
    }
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  function startDrag(e) {
    // Só arrasta se clicou no header (não nos botões)
    const point = e.touches ? e.touches[0] : e;
    dragRef.current = {
      mx: point.clientX, my: point.clientY,
      sx: pos.x, sy: pos.y,
    };
    setDragging(true);
    if (e.cancelable) e.preventDefault();
  }

  useEffect(() => {
    if (!dragging) return;
    function onMove(e) {
      const point = e.touches ? e.touches[0] : e;
      const dx = point.clientX - dragRef.current.mx;
      const dy = point.clientY - dragRef.current.my;
      let nx = dragRef.current.sx + dx;
      let ny = dragRef.current.sy + dy;
      // Limita dentro da viewport
      nx = Math.max(0, Math.min(window.innerWidth - CALC_W, nx));
      ny = Math.max(0, Math.min(window.innerHeight - CALC_H, ny));
      setPos({ x: nx, y: ny });
      if (e.cancelable) e.preventDefault();
    }
    function onEnd() { setDragging(false); }
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onEnd);
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onEnd);
    window.addEventListener("touchcancel", onEnd);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onEnd);
      window.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onEnd);
      window.removeEventListener("touchcancel", onEnd);
    };
  }, [dragging]);

  const fmt = (n) => {
    if (!isFinite(n)) return "Erro";
    const s = (Math.round(n * 10000) / 10000).toString();
    return s.replace(".", ",");
  };
  const parse = (s) => parseFloat(s.replace(",", "."));

  function inputDigit(d) {
    if (justEval || display === "Erro") { setDisplay(d); setJustEval(false); return; }
    setDisplay(display === "0" ? d : display + d);
  }
  function inputDot() {
    if (justEval || display === "Erro") { setDisplay("0,"); setJustEval(false); return; }
    if (!display.includes(",")) setDisplay(display + ",");
  }
  function compute(a, b, oper) {
    switch (oper) {
      case "+": return a + b;
      case "-": return a - b;
      case "÷": return b === 0 ? NaN : a / b;
      default:  return b;
    }
  }
  function setOperator(newOp) {
    const cur = parse(display);
    if (prev !== null && op !== null && !justEval) {
      const r = compute(prev, cur, op);
      setDisplay(fmt(r));
      setPrev(r);
    } else {
      setPrev(cur);
    }
    setOp(newOp);
    setJustEval(true);
  }
  function evaluate() {
    if (prev === null || op === null) return;
    const cur = parse(display);
    const r = compute(prev, cur, op);
    setDisplay(fmt(r));
    setPrev(null);
    setOp(null);
    setJustEval(true);
  }
  function clearAll() { setDisplay("0"); setPrev(null); setOp(null); setJustEval(false); }
  function backspace() {
    if (justEval || display === "Erro" || display.length <= 1) {
      setDisplay("0"); setJustEval(false); return;
    }
    setDisplay(display.slice(0, -1));
  }

  if (!open) return null;
  return (
    <div
      className="calc-popup"
      role="dialog"
      aria-label="Calculadora (arraste pela barra superior para mover)"
      style={{ left: pos.x, top: pos.y, bottom: "auto" }}
    >
      <div className="calc-inner">
        <div
          className={"calc-header" + (dragging ? " dragging" : "")}
          onMouseDown={startDrag}
          onTouchStart={startDrag}
          style={{ cursor: dragging ? "grabbing" : "grab", touchAction: "none" }}
          aria-label="Barra de arrastar"
        >
          <span>⋮⋮ 🧮 CALCULADORA</span>
          <button className="calc-close" onClick={onClose} aria-label="Fechar calculadora">✕</button>
        </div>
        <div className="calc-display" aria-live="polite">{display}</div>
        <div className="calc-grid">
          <button className="calc-btn fn" onClick={clearAll}>AC</button>
          <button className="calc-btn fn" onClick={backspace} aria-label="Apagar">⌫</button>
          <button className="calc-btn fn" disabled style={{ opacity: 0.3 }}> </button>
          <button className="calc-btn op" onClick={() => setOperator("÷")}>÷</button>
          <button className="calc-btn" onClick={() => inputDigit("7")}>7</button>
          <button className="calc-btn" onClick={() => inputDigit("8")}>8</button>
          <button className="calc-btn" onClick={() => inputDigit("9")}>9</button>
          <button className="calc-btn op" onClick={() => setOperator("-")}>−</button>
          <button className="calc-btn" onClick={() => inputDigit("4")}>4</button>
          <button className="calc-btn" onClick={() => inputDigit("5")}>5</button>
          <button className="calc-btn" onClick={() => inputDigit("6")}>6</button>
          <button className="calc-btn op" onClick={() => setOperator("+")}>+</button>
          <button className="calc-btn" onClick={() => inputDigit("1")}>1</button>
          <button className="calc-btn" onClick={() => inputDigit("2")}>2</button>
          <button className="calc-btn" onClick={() => inputDigit("3")}>3</button>
          <button className="calc-btn eq" style={{ gridRow: "span 2" }} onClick={evaluate}>=</button>
          <button className="calc-btn" style={{ gridColumn: "span 2" }} onClick={() => inputDigit("0")}>0</button>
          <button className="calc-btn" onClick={inputDot}>,</button>
        </div>
      </div>
    </div>
  );
}

// === TELAS ===

function Inicio({ onStart, onCred }) {
  return (
    <main className="stage-bg" style={{ minHeight: "100vh", display: "grid", placeItems: "center", padding: 20 }}>
      <div style={{ textAlign: "center", position: "relative", zIndex: 2 }}>
        <h1 className="title-flash" style={{ fontSize: "clamp(44px, 9vw, 100px)", lineHeight: 0.95, margin: "0 0 6px 0" }}>PROBABILIDADE</h1>
        <h1 className="title-flash" style={{ fontSize: "clamp(48px, 10vw, 120px)", lineHeight: 0.95, margin: "0 0 22px 0", letterSpacing: "0.06em" }}>ROXA</h1>
        <p style={{ fontFamily: "Impact, sans-serif", fontSize: 14, letterSpacing: "0.12em", color: "#fff",
          textShadow: "2px 2px 0 #5a0836", margin: "0 0 32px 0" }}>
          OVA CONDIGITAL • RECONSTRUÇÃO PROFMAT/UFVJM
        </p>
        <div style={{ display: "grid", placeItems: "center", marginBottom: 28 }}>
          <OkBall onClick={onStart} pulse />
        </div>
        <div style={{ display: "flex", gap: 12, justifyContent: "center", flexWrap: "wrap" }}>
          <button type="button" className="btn" onClick={onStart} style={{ fontSize: 18, padding: "14px 32px" }}>▶ Jogar</button>
          <button type="button" className="btn ghost" onClick={onCred}>⚽ Créditos</button>
        </div>
        <p style={{ marginTop: 32, fontSize: 13, color: "rgba(255,255,255,0.75)", maxWidth: 480, margin: "32px auto 0", lineHeight: 1.5 }}>
          Calcule probabilidades em situações de torcida! Preencha os totais da tabela, interprete o enunciado e marque o gol da resposta certa.
        </p>
      </div>
    </main>
  );
}

function Fase1({ onHelp }) {
  const [q, setQ] = useState(() => novaQ());
  const [phase, setPhase] = useState("ler");        // ler | escolher | revelado
  const [sel, setSel] = useState(null);
  const [res, setRes] = useState(null);
  const [stats, setStats] = useState({ r: 0, a: 0 });
  // Totais digitados pelo aluno (string para permitir input vazio)
  const [totals, setTotals] = useState({ t1: "", t2: "", th: "", tm: "", tg: "" });
  const [somaResult, setSomaResult] = useState(null);   // null | { t1, t2, th, tm, tg }
  const [somaMsg, setSomaMsg] = useState(null);         // null | "ok" | "errada"
  const [calcOpen, setCalcOpen] = useState(false);      // calculadora visível

  function tentarResponder() {
    // Validar TODOS os totais (5 campos) antes de liberar a espiral
    const r = {
      t1: parseInt(totals.t1, 10) === q.totalsCorretos.t1,
      t2: parseInt(totals.t2, 10) === q.totalsCorretos.t2,
      th: parseInt(totals.th, 10) === q.totalsCorretos.th,
      tm: parseInt(totals.tm, 10) === q.totalsCorretos.tm,
      tg: parseInt(totals.tg, 10) === q.totalsCorretos.tg,
    };
    setSomaResult(r);
    if (r.t1 && r.t2 && r.th && r.tm && r.tg) {
      setSomaMsg("ok");
      setTimeout(() => {
        setPhase("escolher"); setSel(null); setSomaMsg(null);
      }, 700);
    } else {
      setSomaMsg("errada");
    }
  }

  function confirmar() {
    if (sel === null) return;
    const certo = sel === q.pos;
    setRes({ ok: certo });
    setPhase("revelado");
    setStats((s) => ({ r: s.r + 1, a: s.a + (certo ? 1 : 0) }));
  }

  function proxima() {
    setQ(novaQ());
    setSel(null); setRes(null);
    setTotals({ t1: "", t2: "", th: "", tm: "", tg: "" });
    setSomaResult(null); setSomaMsg(null);
    setPhase("ler");
  }

  const aprov = stats.r ? Math.round((stats.a / stats.r) * 100) : 0;

  return (
    <main className="stage-bg" style={{ minHeight: "100vh", padding: 14 }}>
      <div style={{ maxWidth: 1080, margin: "0 auto", position: "relative", zIndex: 2 }}>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14, alignItems: "center", justifyContent: "center" }}>
          <span className="chip">Respondidas <strong>{stats.r}</strong></span>
          <span className="chip">Acertos <strong>{stats.a}</strong></span>
          <span className="chip">Aproveit. <strong>{aprov}%</strong></span>
        </div>
        <div className="metal-frame">
          <div className="metal-inner" style={{ padding: 18 }}>
            <div className="grid2" style={{ display: "grid", gridTemplateColumns: "minmax(320px, 420px) 1fr", gap: 18, alignItems: "start" }}>
              {/* COLUNA ESQUERDA: tabela com totais editáveis */}
              <div>
                <Tabela
                  q={q}
                  totals={totals}
                  setTotals={(t) => { setTotals(t); setSomaResult(null); setSomaMsg(null); }}
                  locked={phase !== "ler"}
                  somaResult={somaResult}
                />
                {phase === "ler" && (
                  <div style={{ textAlign: "center", marginTop: 6 }}>
                    {somaMsg === "errada" && <div className="soma-aviso">⚠ Soma errada!</div>}
                    {somaMsg === "ok"     && <div className="soma-ok">✓ Totais corretos!</div>}
                  </div>
                )}
              </div>

              {/* COLUNA DIREITA: enunciado + interação */}
              <div style={{ minHeight: 360 }}>
                {phase === "ler" && (<>
                  <QPanel q={q} />
                  <p style={{
                    textAlign: "center", fontFamily: "Impact, sans-serif", color: "#fff",
                    textShadow: "2px 2px 0 #5a0836", fontSize: 12,
                    margin: "12px 0 4px 0", letterSpacing: "0.05em",
                  }}>
                    1. PREENCHA OS TOTAIS DA TABELA. &nbsp; 2. CLIQUE EM RESPONDER.
                  </p>
                  <div style={{ display: "flex", gap: 10, marginTop: 18, justifyContent: "center", flexWrap: "wrap" }}>
                    <button type="button" className="btn" onClick={tentarResponder}>⚽ Responder</button>
                    <button type="button" className="btn ghost" onClick={() => onHelp("geral")}>? Ajuda</button>
                  </div>
                </>)}
                {phase === "escolher" && (<>
                  <QPanel q={q} />
                  <p style={{ textAlign: "center", fontFamily: "Impact, sans-serif", color: "#fff",
                    textShadow: "2px 2px 0 #5a0836", fontSize: 12, margin: "12px 0 4px 0", letterSpacing: "0.05em" }}>
                    1. TOQUE NA ALTERNATIVA. &nbsp; 2. CLIQUE NA BOLA PARA CONFIRMAR.
                  </p>
                  <div style={{ position: "relative", marginTop: 4 }}>
                    <div style={{ position: "absolute", left: "50%", top: "50%", transform: "translate(-50%, -50%)", zIndex: 2 }}>
                      <OkBall onClick={confirmar} disabled={sel === null} pulse={sel !== null} />
                    </div>
                    <Spiral q={q} sel={sel} onSel={setSel} />
                  </div>
                </>)}
                {phase === "revelado" && (<>
                  <QPanel q={q} />
                  <div style={{ marginTop: 14 }}>
                    <Feedback res={res} q={q} onNext={proxima}
                      onHelp={() => onHelp(topicoPorTipo[q.tipo] || "geral")} />
                  </div>
                </>)}
              </div>
            </div>
          </div>
        </div>
        <button type="button" className="btn small ghost" onClick={() => onHelp("geral")}
          style={{ position: "fixed", bottom: 16, right: 16, zIndex: 10 }}>? Ajuda</button>
        <button type="button" className="btn small" onClick={() => setCalcOpen(!calcOpen)}
          style={{ position: "fixed", bottom: 16, left: 16, zIndex: 10 }}
          aria-label={calcOpen ? "Fechar calculadora" : "Abrir calculadora"}>
          🧮 {calcOpen ? "Fechar" : "Calculadora"}
        </button>
        <Calculator open={calcOpen} onClose={() => setCalcOpen(false)} />
      </div>
    </main>
  );
}

