// === APP ===
export default function App() {
  const [screen, setScreen] = useState("inicio");
  const [helpOpen, setHelpOpen] = useState(false);
  const [helpTopic, setHelpTopic] = useState("geral");
  function openHelp(t = "geral") { setHelpTopic(t); setHelpOpen(true); }
  return (
    <>
      <style>{CSS}</style>
      {screen === "inicio" && <Inicio onStart={() => setScreen("fase1")} onCred={() => setScreen("cred")} />}
      {screen === "fase1" && <Fase1 onHelp={openHelp} />}
      {screen === "cred" && <Cred onBack={() => setScreen("inicio")} />}
      {screen !== "inicio" && (
        <button type="button" className="btn small ghost" onClick={() => setScreen("inicio")}
          style={{ position: "fixed", top: 14, left: 14, zIndex: 10 }}>← Início</button>
      )}
      <Help open={helpOpen} topic={helpTopic} setTopic={setHelpTopic} onClose={() => setHelpOpen(false)} />
    </>
  );
}
